// Function to check if the user has granted permission to access their location
function checkLocationPermission() {
    if (navigator.geolocation) {
        return true;
    } else {
        console.log("Geolocation is not supported by this browser.");
        return false;
    }
}

// Function to request location permission from the user
function requestLocationPermission() {
    if (checkLocationPermission()) {
        navigator.geolocation.getCurrentPosition(showPosition, showError);
    } else {
        console.log("Location permission is not granted.");
    }
}

// Function to show the user's position
function showPosition(position) {
    const latitude = position.coords.latitude;
    const longitude = position.coords.longitude;
    console.log(`Latitude: ${latitude}, Longitude: ${longitude}`);
}

// Function to handle errors when getting the user's position
function showError(error) {
    switch(error.code) {
        case error.PERMISSION_DENIED:
            console.log("User denied the request for Geolocation.");
            break;
        case error.POSITION_UNAVAILABLE:
            console.log("Location information is unavailable.");
            break;
        case error.TIMEOUT:
            console.log("The request to get user location timed out.");
            break;
        case error.UNKNOWN_ERROR:
            console.log("An unknown error occurred.");
            break;
    }
}

// Request location permission when the page loads
document.addEventListener('DOMContentLoaded', function() {
    requestLocationPermission();
});
